def synthetic_entry(directory, case):
    name, split, seed, duration, rate, bpm, kind = case
    directory.mkdir(parents=True, exist_ok=True)
    path = directory / f"{name}.f32le"
    metadata_path = directory / f"{name}.json"
    specification = {
        "generator": GENERATOR_VERSION,
        "name": name,
        "split": split,
        "seed": seed,
        "duration": duration,
        "sample_rate": rate,
        "bpm": bpm,
        "kind": kind,
    }
    if path.exists() and metadata_path.exists():
        cached = json.loads(metadata_path.read_text())
        if cached.get("specification") == specification and cached[
            "pcm_sha256"
        ] == sha256(path):
            cached["pcm_path"] = str(path.resolve())
            return cached

    rng = random.Random(seed)
    frame_count = round(duration * rate)
    mono = array.array("f", [0.0]) * frame_count
    if kind in {"bass_hats", "offbeats", "noise", "jitter"}:
        for frame in range(frame_count):
            noise = rng.uniform(-1.0, 1.0)
            if kind == "bass_hats":
                value = 0.16 * math.sin(2 * math.pi * 73 * frame / rate)
                value += 0.04 * math.sin(2 * math.pi * 146 * frame / rate)
                value += 0.006 * noise
            else:
                value = (0.08 if kind == "noise" else 0.008) * noise
            mono[frame] = value

    origin = 0.137 + rng.uniform(0.0, 0.12)
    beats = []
    ideal_beats = []
    position = origin
    index = 0
    while bpm is not None and position < duration:
        ideal_beats.append(position)
        displacement = rng.gauss(0, 0.006) if kind == "jitter" else 0
        beats.append(round((position + displacement) * rate) / rate)
        index += 1
        if kind == "drift":
            slope = 45 / (duration - origin)
            relative = (
                120
                * index
                / (bpm + math.sqrt(bpm * bpm + 120 * slope * index))
            )
            position = origin + relative
        elif kind == "step":
            position += 60 / (112 if position < duration / 2 else 136)
        else:
            position = origin + index * 60 / bpm

    kick = [
        math.exp(-80 * offset / rate)
        * (
            0.72 * math.cos(2 * math.pi * 83 * offset / rate)
            + 0.20 * math.cos(2 * math.pi * 170 * offset / rate)
            + 0.08 * math.cos(2 * math.pi * 2100 * offset / rate)
        )
        for offset in range(round(0.09 * rate))
    ]
    hat = [
        math.exp(-260 * offset / rate)
        * rng.uniform(-1.0, 1.0)
        * (1 if offset % 2 else -1)
        for offset in range(round(0.035 * rate))
    ]

    def add_pulse(start_seconds, pulse, gain):
        start = round(start_seconds * rate)
        if start < 0 or start >= frame_count:
            return
        for offset in range(min(len(pulse), frame_count - start)):
            mono[start + offset] += gain * pulse[offset]

    for index, beat in enumerate(beats):
        gain = 0.58
        if kind == "accent":
            gain *= 1 if index % 4 == 0 else 0.18
        elif kind == "levels":
            gain *= (0.20, 1.0, 0.42, 0.10)[min(3, int(4 * beat / duration))]
        elif kind == "bass_hats":
            gain = 0.22
        else:
            gain *= rng.uniform(0.75, 1.0)
        add_pulse(beat, kick, gain)
        if kind in {"bass_hats", "offbeats"}:
            interval = 60 / bpm
            for division in (0.25, 0.50, 0.75):
                add_pulse(
                    ideal_beats[index] + interval * division,
                    hat,
                    (0.09 if kind == "bass_hats" else 0.17)
                    * rng.uniform(0.7, 1.0),
                )

    stereo = array.array("f")
    for value in mono:
        # Both stereo polarities exercise channel energy preservation.
        stereo.extend(
            (value, -0.93 * value if seed % 4 == 3 else 0.93 * value)
        )
    if sys.byteorder != "little":
        stereo.byteswap()
    with path.open("wb") as output:
        stereo.tofile(output)
    digest = sha256(path)
    truth = {
        "generator": GENERATOR_VERSION,
        "kind": kind,
        "seed": seed,
        "beat_times_seconds": beats,
        "constant_bpm": bpm if kind not in {"step", "drift"} else None,
        "expected_noresult": kind in {"noise", "silence", "step", "drift"},
        "expectation_scope": (
            "constant-tempo output should be declined for changing tempo or "
            "nonrhythmic inputs; numerical candidate metrics remain available"
        ),
        "tempo_changes": (
            [
                {
                    "time_seconds": next(
                        t for t in beats if t >= duration / 2
                    ),
                    "bpm_before": 112,
                    "bpm_after": 136,
                }
            ]
            if kind == "step"
            else []
        ),
    }
    result = {
        "name": name,
        "pcm_path": str(path.resolve()),
        "sample_rate": rate,
        "channels": 2,
        "duration": duration,
        "source_sha256": digest,
        "pcm_sha256": digest,
        "source_kind": "generated-float32le-pcm",
        "split": split,
        "truth": truth,
        "specification": specification,
    }
    metadata_path.write_text(json.dumps(result, indent=2) + "\n")
    return result


def load_entries(arguments, output):
    entries = []
    if arguments.manifest and not arguments.synthetic_only:
        manifest_path = Path(arguments.manifest).resolve()
        contents = json.loads(manifest_path.read_text())
        items = (
            contents.get("files", contents.get("inputs", []))
            if isinstance(contents, dict)
            else contents
        )
        if not isinstance(items, list):
            raise ValueError(
                "manifest must be a list or contain files/inputs list"
            )
        for original in items:
            entry = dict(original)
            path = Path(entry["pcm_path"])
            if not path.is_absolute():
                path = manifest_path.parent / path
            entry["pcm_path"] = str(path.resolve())
            entry.setdefault("name", path.name)
            entry.setdefault("split", "recording")
            entries.append(entry)
    if not arguments.skip_synthetic:
        for case in SYNTHETIC_CASES:
            if (
                arguments.synthetic_split != "all"
                and case[1] != arguments.synthetic_split
            ):
                continue
            if (
                arguments.synthetic_case
                and case[0] not in arguments.synthetic_case
            ):
                continue
            print(f"Preparing {case[0]} ({case[1]})", flush=True)
            entries.append(synthetic_entry(output / "synthetic-pcm", case))
    if not entries:
        raise ValueError("no PCM inputs selected")
    for index, entry in enumerate(entries):
        path = Path(entry["pcm_path"])
        if not path.is_file():
            raise ValueError(f"PCM file does not exist: {path}")
        rate = float(entry["sample_rate"])
        if not math.isfinite(rate) or not 1000 <= rate <= 384000:
            raise ValueError(f"invalid sample_rate for {path}")
        if entry["channels"] != 2 or path.stat().st_size % 8:
            raise ValueError(f"complete stereo float32 PCM required: {path}")
        actual_duration = path.stat().st_size / 8 / rate
        if actual_duration <= 0:
            raise ValueError(f"empty PCM input: {path}")
        declared_duration = entry.get(
            "duration", entry.get("duration_seconds")
        )
        if (
            declared_duration is not None
            and abs(float(declared_duration) - actual_duration) > 1 / rate
        ):
            raise ValueError(
                f"manifest duration differs from PCM frame count: {path}"
            )
        digest = sha256(path)
        if entry.get("pcm_sha256") != digest:
            raise ValueError(
                f"manifest PCM SHA256 absent or mismatched: {path}"
            )
        if not entry.get("source_sha256"):
            raise ValueError(f"source_sha256 is required: {path}")
        entry["duration_seconds"] = actual_duration
        name_digest = hashlib.sha256(entry["name"].encode()).hexdigest()[:10]
        entry["input_id"] = f"{index:03d}_{name_digest}"
    return entries


def score_report(entry, report):
    report["truth_metrics"] = truth_metrics(
        entry,
        {
            **report,
            "status": "success" if report.get("accepted") else "noresult",
        },
        TOLERANCE_SECONDS,
    )
    has_candidate = (
        report.get("bpm") is not None
        and report.get("beat_phase_seconds") is not None
    )
    report["diagnostic_truth_metrics"] = truth_metrics(
        entry,
        {
            **report,
            "status": "success" if has_candidate else "noresult",
            "beat_times_seconds": report.get(
                "diagnostic_beat_times_seconds", []
            ),
        },
        TOLERANCE_SECONDS,
    )
    expectation = model_expectation(entry, report["profile"])
    report["model_expectation"] = expectation
    report["expected_noresult"] = expectation["expected_noresult"]
    report["truth_signal_kind"] = expectation["signal_kind"]
    truth = entry.get("truth")
    report["truth_expected_noresult"] = (
        truth.get("expected_noresult", False) if truth is not None else None
    )
    if report.get("status") == "error" or entry.get("truth") is None:
        behavior_met = None
    elif expectation["expected_noresult"] is not None:
        behavior_met = (
            bool(report.get("accepted")) != expectation["expected_noresult"]
        )
    else:
        behavior_met = not report.get("accepted") or (
            report.get("best_fit_estimate") is True
            and report.get("constant_supported") is False
        )
    report["model_behavior_expectation_met"] = behavior_met


def model_expectation(entry, profile):
    truth = entry.get("truth")
    if truth is None:
        return {
            "signal_kind": "unannotated",
            "expected_noresult": None,
            "behavior": "acceptance is not a beat or tempo accuracy score",
        }
    if not truth.get("beat_times_seconds"):
        return {
            "signal_kind": "nonrhythmic",
            "expected_noresult": True,
            "behavior": "noise and silence must be declined in every mode",
        }
    if truth.get("constant_bpm") is not None:
        return {
            "signal_kind": "constant_rhythm",
            "expected_noresult": False,
            "behavior": "constant estimate expected; beat truth scores it",
        }
    if profile == "completion":
        return {
            "signal_kind": "varying_tempo",
            "expected_noresult": None,
            "behavior": (
                "a best-fit constant estimate is permitted when marked "
                "best_fit_estimate=true and constant_supported=false; "
                "it does not track the true tempo changes"
            ),
        }
    return {
        "signal_kind": "varying_tempo",
        "expected_noresult": True,
        "behavior": "strict constant support is absent; decline expected",
    }


def representative_local_windows(evidence):
    best = {}
    for item in evidence:
        key = (item["start_seconds"], item["end_seconds"])
        if key not in best or item.get("vote_weight", 0) > best[key].get(
            "vote_weight", 0
        ):
            best[key] = item
    return [
        {"start_seconds": start, "end_seconds": end, "bpm": item.get("bpm")}
        for (start, end), item in sorted(best.items())
    ]


def compare_rows(reference, candidate):
    result = {
        "input_name": reference["input_name"],
        "reference_config": reference["config"],
        "candidate_config": candidate["config"],
        "identical_pcm": reference["pcm_sha256"] == candidate["pcm_sha256"],
        "reference_status": reference.get("status"),
        "candidate_status": candidate.get("status"),
        "agreement_is_not_accuracy": True,
        "analysis_time_ratio_candidate_over_reference": (
            candidate["analysis_ms"] / reference["analysis_ms"]
            if reference.get("analysis_ms", 0) > 0
            and candidate.get("analysis_ms") is not None
            else None
        ),
    }
    if reference.get("bpm") is not None and candidate.get("bpm") is not None:
        result["diagnostic_bpm_difference"] = (
            candidate["bpm"] - reference["bpm"]
        )
        result["diagnostic_beat_agreement"] = beat_metrics(
            reference.get("diagnostic_beat_times_seconds", []),
            candidate.get("diagnostic_beat_times_seconds", []),
            reference["duration_seconds"],
            TOLERANCE_SECONDS,
        )
    return result


def summaries(rows):
    result = []
    for split in sorted({row["split"] for row in rows}):
        for name, _, _ in CONFIGURATIONS:
            subset = [
                row
                for row in rows
                if row["split"] == split and row["config"] == name
            ]
            if not subset:
                continue
            diagnostic_f1 = [
                row["diagnostic_truth_metrics"]["beats"]["f1"]
                for row in subset
                if row.get("truth_signal_kind") == "constant_rhythm"
                and "beats" in row["diagnostic_truth_metrics"]
            ]
            qualified_drift = [
                abs(
                    row["diagnostic_truth_metrics"]["beats"][
                        "drift_slope_ms_per_minute"
                    ]
                )
                for row in subset
                if row.get("truth_signal_kind") == "constant_rhythm"
                and row["diagnostic_truth_metrics"]
                .get("beats", {})
                .get("drift_fit_qualified")
            ]
            result.append(
                {
                    "split": split,
                    "config": name,
                    "inputs": len(subset),
                    "status_counts": dict(
                        Counter(row.get("status") for row in subset)
                    ),
                    "truth_available": sum(
                        row["truth_metrics"]["ground_truth_available"]
                        for row in subset
                    ),
                    "expected_noresult": sum(
                        row.get("expected_noresult") is True for row in subset
                    ),
                    "expected_noresult_declined": sum(
                        row.get("expected_noresult") is True
                        and row.get("status") in {"rejected", "nocandidate"}
                        for row in subset
                    ),
                    "constant_rhythm_inputs": sum(
                        row.get("truth_signal_kind") == "constant_rhythm"
                        for row in subset
                    ),
                    "constant_rhythm_accepted": sum(
                        row.get("truth_signal_kind") == "constant_rhythm"
                        and row.get("accepted", False)
                        for row in subset
                    ),
                    "nonrhythmic_inputs": sum(
                        row.get("truth_signal_kind") == "nonrhythmic"
                        for row in subset
                    ),
                    "nonrhythmic_declined": sum(
                        row.get("truth_signal_kind") == "nonrhythmic"
                        and row.get("status") in {"rejected", "nocandidate"}
                        for row in subset
                    ),
                    "varying_tempo_inputs": sum(
                        row.get("truth_signal_kind") == "varying_tempo"
                        for row in subset
                    ),
                    "varying_tempo_accepted": sum(
                        row.get("truth_signal_kind") == "varying_tempo"
                        and row.get("accepted", False)
                        for row in subset
                    ),
                    "varying_tempo_best_fit_estimates": sum(
                        row.get("truth_signal_kind") == "varying_tempo"
                        and row.get("accepted", False)
                        and row.get("best_fit_estimate", False)
                        and row.get("constant_supported") is False
                        for row in subset
                    ),
                    "model_behavior_violations": sum(
                        row.get("model_behavior_expectation_met") is False
                        for row in subset
                    ),
                    "diagnostic_f1_available_constant_rhythms": len(
                        diagnostic_f1
                    ),
                    "diagnostic_f1_mean_available_constant_rhythms": (
                        statistics.mean(diagnostic_f1)
                        if diagnostic_f1
                        else None
                    ),
                    "qualified_abs_drift_mean_ms_per_minute": (
                        statistics.mean(qualified_drift)
                        if qualified_drift
                        else None
                    ),
                    "qualified_drift_inputs": len(qualified_drift),
                    "mean_analysis_ms": (
                        statistics.mean(
                            row["analysis_ms"]
                            for row in subset
                            if "analysis_ms" in row
                        )
                        if any("analysis_ms" in row for row in subset)
                        else None
                    ),
                }
            )
    return result


def markdown_report(result):
    lines = [
        "<!-- Autonomously generated by an AI agent. -->",
        "",
        "# Phase-grid completion ablation",
        "",
        "Each row runs a fresh standalone process on the same SHA256-verified "
        "native-decoder float32 stereo PCM. No recording is re-decoded "
        "in this runner.",
        "",
        "Synthetic truth uses exact rendered pulse times. Beat metrics import "
        "the unchanged compare_phasegrid.py chronological one-to-one matcher "
        "with a fixed 70 ms tolerance and the same edge exclusion. Diagnostic "
        "F1/phase/drift assess numerical candidates even after rejection; "
        "accepted output is scored separately. "
        "A rejected diagnostic candidate is never a published beat grid.",
        "",
        "The completion profile uses BestFitConstant, matching a native "
        "Constant request: coherent local rhythms may produce a best-fit "
        "constant estimate even when a single grid cannot track the signal. "
        "completion-strict preserves the StrictConstant diagnostic policy. "
        "The original truth expected_noresult flag describes strict support; "
        "per-row model_expectation states the chosen mode's expectation.",
        "",
        "Uploaded recordings without external annotations have no accuracy "
        "scores. Candidate agreement, acceptance, and timing on these "
        "recordings cannot establish "
        "beat or tempo quality.",
        "",
        "The calibration and held-out synthetic splits use disjoint fixed "
        "seeds and different tempos/durations. No per-track parameter fitting "
        "is used. The held-out split is independent synthetic variation, "
        "not a blind external corpus; any subsequent algorithm changes made "
        "after viewing these results invalidate a claim of untouched holdout "
        "performance. Default thresholds are the shared library defaults.",
        "",
        "Timing is a single process measurement per cell, excluding PCM "
        "decode/hash/read and final JSON file output. Core timing includes "
        "diagnostic construction; it is not a controlled speed benchmark. "
        "Drift is shown only with at least 80% "
        "beat/span coverage and 8 seconds of matched span.",
        "",
        "| Input | Split | Frontend/policy | Status | Best fit | "
        "Constant supported | Rhythmic coverage | Events | BPM | "
        "Published GT F1 | Diagnostic GT F1 | Median phase error ms | "
        "Qualified drift ms/min | Front ms | Core ms |",
        "| --- | --- | --- | --- | --- | --- | ---: | ---: | ---: | ---: "
        "| ---: | ---: | ---: | ---: | ---: |",
    ]

    def number(value, digits=3):
        return (
            f"{value:.{digits}f}" if isinstance(value, (int, float)) else "—"
        )

    for row in result["measurements"]:
        diagnostic = row.get("diagnostic_truth_metrics", {}).get("beats", {})
        published = row.get("truth_metrics", {}).get("beats", {})
        lines.append(
            "| "
            + " | ".join(
                (
                    row["input_name"].replace("|", "\\|"),
                    row["split"],
                    row["frontend"] + "/" + row["profile"],
                    row.get("status", "error"),
                    str(row.get("best_fit_estimate", "—")),
                    str(row.get("constant_supported", "—")),
                    number(row.get("rhythmic_coverage")),
                    str(row.get("events", "—")),
                    number(row.get("bpm")),
                    number(published.get("f1")),
                    number(diagnostic.get("f1")),
                    number(diagnostic.get("median_signed_error_ms")),
                    number(diagnostic.get("drift_slope_ms_per_minute")),
                    number(row.get("frontend_ms")),
                    number(row.get("core_ms")),
                )
            )
            + " |"
        )
    lines.extend(
        [
            "",
            "Noise and silence should be declined in every mode. Changing "
            "tempo is excluded from constant-rhythm quality means. Best-fit "
            "mode may emit a flagged constant estimate for changing tempo; "
            "strict mode should decline it. Published and diagnostic beat F1 "
            "remain visible for changing tempo, including low scores. A "
            "constant estimate does not track those tempo changes.",
            "",
            "| Split | Frontend/policy | Constant accepted/total | "
            "Nonrhythmic declines/total | Varying accepted/total | "
            "Flagged varying best-fit estimates | "
            "Diagnostic F1 mean (available constant cases) | "
            "Candidates scored |",
            "| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: |",
        ]
    )
    for item in result["summaries"]:
        f1_mean = item["diagnostic_f1_mean_available_constant_rhythms"]
        lines.append(
            f"| {item['split']} | {item['config']} | "
            f"{item['constant_rhythm_accepted']}/"
            f"{item['constant_rhythm_inputs']} | "
            f"{item['nonrhythmic_declined']}/"
            f"{item['nonrhythmic_inputs']} | "
            f"{item['varying_tempo_accepted']}/"
            f"{item['varying_tempo_inputs']} | "
            f"{item['varying_tempo_best_fit_estimates']} | "
            f"{number(f1_mean)} | "
            f"{item['diagnostic_f1_available_constant_rhythms']} |"
        )
    if result["errors"]:
        lines.extend(["", "Errors:", ""])
        for error in result["errors"]:
            lines.append("- " + json.dumps(error, ensure_ascii=False))
    lines.extend(
        ["", "<!-- End of autonomously generated AI-agent report. -->", ""]
    )
    return "\n".join(lines)


def run(arguments):
    output = Path(arguments.output_dir).resolve()
    output.mkdir(parents=True, exist_ok=True)
    probe = Path(arguments.probe).resolve()
    if not probe.is_file():
        raise ValueError(f"probe executable does not exist: {probe}")
    entries = load_entries(arguments, output)
    (output / "inputs.json").write_text(
        json.dumps(entries, indent=2, ensure_ascii=False) + "\n"
    )
    reports_directory = output / "reports"
    reports_directory.mkdir(exist_ok=True)
    result = {
        "schema_version": 2,
        "experimental": True,
        "generated_by_ai": True,
        "tolerance_seconds": TOLERANCE_SECONDS,
        "probe": str(probe),
        "probe_sha256": sha256(probe),
        "generator_version": GENERATOR_VERSION,
        "synthetic_split_scope": (
            "disjoint deterministic seeds; shared fixed defaults; "
            "no per-track fitting"
        ),
        "accuracy_scope": (
            "synthetic rendered beat truth and optional external "
            "annotations only"
        ),
        "diagnostic_scope": (
            "rejected numerical candidates are evaluated separately "
            "and are never published grids"
        ),
        "source_manifest": (
            str(Path(arguments.manifest).resolve())
            if arguments.manifest
            else None
        ),
        "measurements": [],
        "pairs": [],
        "summaries": [],
        "errors": [],
    }
    for entry in entries:
        by_configuration = {}
        for configuration, frontend, profile in CONFIGURATIONS:
            report_path = (
                reports_directory / f"{entry['input_id']}_{configuration}.json"
            )
            command = [
                str(probe),
                "--pcm",
                entry["pcm_path"],
                "--sample-rate",
                str(entry["sample_rate"]),
                "--channels",
                "2",
                "--frontend",
                frontend,
                "--profile",
                profile,
                "--output",
                str(report_path),
            ]
            if report_path.exists():
                report_path.unlink()
            start = time.monotonic()
            try:
                completed = subprocess.run(
                    command,
                    capture_output=True,
                    text=True,
                    timeout=arguments.timeout,
                )
                report = json.loads(report_path.read_text())
                if (
                    completed.returncode != 0
                    or report.get("status") == "error"
                ):
                    raise ValueError(
                        report.get("error", completed.stderr[-2000:])
                    )
                if (
                    report["decoded_frames"]
                    != Path(entry["pcm_path"]).stat().st_size // 8
                ):
                    raise ValueError(
                        "probe frame count differs from verified PCM"
                    )
                if (
                    report["sample_rate"] != entry["sample_rate"]
                    or report["channels"] != 2
                ):
                    raise ValueError(
                        "probe audio format differs from verified PCM"
                    )
            except (OSError, ValueError, subprocess.TimeoutExpired) as error:
                report = {
                    "status": "error",
                    "accepted": False,
                    "error": str(error),
                }
                result["errors"].append(
                    {
                        "input": entry["name"],
                        "config": configuration,
                        "error": str(error),
                    }
                )
            report.update(
                {
                    "input_name": entry["name"],
                    "input_id": entry["input_id"],
                    "config": configuration,
                    "frontend": frontend,
                    "profile": profile,
                    "split": entry["split"],
                    "source_sha256": entry["source_sha256"],
                    "pcm_sha256": entry["pcm_sha256"],
                    "duration_seconds": entry["duration_seconds"],
                    "process_wall_ms": (time.monotonic() - start) * 1000,
                    "local_bpm_windows": representative_local_windows(
                        report.get("local_evidence", [])
                    ),
                }
            )
            score_report(entry, report)
            result["measurements"].append(report)
            by_configuration[configuration] = report
            print(
                f"{entry['name']} | {frontend}/{profile} | "
                f"{report['status']} | BPM {report.get('bpm')}",
                flush=True,
            )
        baseline = by_configuration[CONFIGURATIONS[0][0]]
        for configuration, _, _ in CONFIGURATIONS[1:]:
            result["pairs"].append(
                compare_rows(baseline, by_configuration[configuration])
            )
        result["summaries"] = summaries(result["measurements"])
        (output / "summary.json").write_text(
            json.dumps(result, indent=2, ensure_ascii=False, allow_nan=False)
            + "\n"
        )
        (output / "summary.md").write_text(markdown_report(result))
    return 1 if result["errors"] else 0


class ModelSemanticsTests(unittest.TestCase):
    def scored_rhythm(self, profile, varying):
        beats = [0.2 + 0.5 * index for index in range(64)]
        if varying:
            beats = beats[:32] + [16.2 + 0.4 * index for index in range(40)]
        entry = {
            "truth": {
                "beat_times_seconds": beats,
                "constant_bpm": None if varying else 120,
                "expected_noresult": varying,
            }
        }
        before = json.dumps(entry, sort_keys=True)
        predicted = (
            [0.45 + 0.5 * index for index in range(64)] if varying else beats
        )
        report = {
            "profile": profile,
            "config": "new_frontend_new_policy",
            "split": "held-out",
            "status": "accepted",
            "accepted": True,
            "best_fit_estimate": varying and profile == "completion",
            "constant_supported": not varying,
            "bpm": 120,
            "beat_phase_seconds": 0.45 if varying else 0.2,
            "duration_seconds": 32,
            "beat_times_seconds": predicted,
            "diagnostic_beat_times_seconds": predicted,
        }
        score_report(entry, report)
        self.assertEqual(json.dumps(entry, sort_keys=True), before)
        return report

    def test_varying_best_fit_keeps_low_truth_score_and_mode_flags(self):
        report = self.scored_rhythm("completion", varying=True)
        self.assertTrue(report["truth_expected_noresult"])
        self.assertIsNone(report["expected_noresult"])
        self.assertTrue(report["model_behavior_expectation_met"])
        self.assertLess(report["truth_metrics"]["beats"]["f1"], 0.5)
        strict = self.scored_rhythm("completion-strict", varying=True)
        self.assertFalse(strict["model_behavior_expectation_met"])
        self.assertEqual(
            strict["truth_metrics"]["beats"],
            report["truth_metrics"]["beats"],
        )

    def test_varying_estimate_is_excluded_from_constant_quality_mean(self):
        constant = self.scored_rhythm("completion", varying=False)
        varying = self.scored_rhythm("completion", varying=True)
        summary = summaries([constant, varying])[0]
        self.assertEqual(summary["constant_rhythm_inputs"], 1)
        self.assertEqual(
            summary["diagnostic_f1_mean_available_constant_rhythms"],
            1,
        )
        self.assertEqual(summary["varying_tempo_accepted"], 1)
        self.assertEqual(summary["varying_tempo_best_fit_estimates"], 1)

    def test_nonrhythmic_input_remains_negative_in_every_mode(self):
        entry = {
            "truth": {
                "beat_times_seconds": [],
                "constant_bpm": None,
                "expected_noresult": True,
            }
        }
        for _, _, profile in CONFIGURATIONS:
            report = {
                "profile": profile,
                "status": "rejected",
                "accepted": False,
            }
            score_report(entry, report)
            self.assertTrue(report["expected_noresult"])
            self.assertTrue(report["truth_metrics"]["noresult_expected"])
            self.assertTrue(report["model_behavior_expectation_met"])


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--probe", default="build/phasegrid-completion-probe")
    parser.add_argument("--manifest")
    parser.add_argument("--output-dir", default="build/phasegrid-completion")
    parser.add_argument("--skip-synthetic", action="store_true")
    parser.add_argument("--synthetic-only", action="store_true")
    parser.add_argument(
        "--synthetic-split",
        choices=("all", "calibration", "held-out"),
        default="all",
    )
    parser.add_argument(
        "--synthetic-case",
        action="append",
        choices=tuple(case[0] for case in SYNTHETIC_CASES),
    )
    parser.add_argument("--timeout", type=float, default=300)
    parser.add_argument(
        "--self-test",
        action="store_true",
        help="run the existing shared metric tests",
    )
    arguments = parser.parse_args()
    if arguments.self_test:
        suite = unittest.TestSuite(
            unittest.defaultTestLoader.loadTestsFromTestCase(case)
            for case in (MetricTests, ModelSemanticsTests)
        )
        return (
            0
            if unittest.TextTestRunner(verbosity=2).run(suite).wasSuccessful()
            else 1
        )
    if not math.isfinite(arguments.timeout) or arguments.timeout <= 0:
        parser.error("timeout must be finite and positive")
    if arguments.skip_synthetic and arguments.synthetic_only:
        parser.error(
            "--skip-synthetic and --synthetic-only cannot be combined"
        )
    try:
        return run(arguments)
    except (ValueError, OSError, KeyError, json.JSONDecodeError) as error:
        print(str(error), file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
